  const horizontal=e.key==="ArrowLeft"||e.key==="ArrowRight";
  setLayout(l=>({...l,palettes:l.palettes.map(a=>a.id===p.id?{...a,...(horizontal?{width:bound(r.width+(e.key==="ArrowLeft"?-30:30),120,1100)}:{height:bound(r.height+(e.key==="ArrowUp"?-30:30),58,1000)})}:a)}));
