  const w=d?d.width:p.width,h=d?d.height:p.height;
  return {...(d?{left:d.left,top:d.top,transform:"none",maxHeight:`calc(100% - ${d.top+6}px)`}:{left:`calc(6px + ${p.x*100}% - ${p.x*12}px)`,top:`calc(6px + ${p.y*100}% - ${p.y*12}px)`,transform:`translate(${-p.x*100}%,${-p.y*100}%)`}),...(w?{width:w}:{}),...(h?{height:h}:{}),...(w?{maxWidth:"calc(100% - 12px)"}:{})};
