 // QGIS toolbar order: Dự án | Điều hướng | Thuộc tính | Số hóa | Xử lý | Xuất. One button per command; the rest live in the menus.
 const groups:Record<string,React.ReactNode>={data:<><GisButton icon="add" label="Thêm dữ liệu (Ctrl+L)" run={openLayer}/>{c("NEWLAYER","layer")}{c("SAVE","save")}<GisButton icon="reload" label="Làm mới" run={refresh} disabled={editing}/></>,map:<><GisButton icon="hand" label="Di chuyển bản đồ (A)" active={mouseMode==="pan"&&!mode} run={pan}/><GisButton icon="select" label="Chọn đối tượng (A)" active={mouseMode==="select"&&!mode} run={select}/>{c("ZI","plus")}{c("ZO","minus")}{c("ZE","extent")}{c("ZL","layers")}</>,attr:<>{c("SELPOLY","polygon")}<GisButton icon="table" label="Bảng thuộc tính (F6)" run={openTable} active={table}/>{c("QUERY","query")}{c("DIST","ruler",mode==="distance")}{c("AREA","area",mode==="area")}</>,edit:<>{c("EDIT","edit")}{c("UNDO","undo")}{c("REDO","reload")}{c("POINT","point",mode==="point")}{c("LINE","line",mode==="line")}{c("POLYGON","polygon",mode==="polygon")}{c("MOVE","hand")}{c("VERTEX","select")}{c("SNAP","plugin",snap)}</>,analysis:<>{c("TOOLBOX","settings")}{c("BUFFER","buffer")}{c("CLIP","clip")}</>,output:<>{c("LAYOUT","table")}{c("EXPORT","export")}</>};
