const SCALES=[500,1000,2000,2500,5000,10000,25000,50000,100000,250000,500000,1000000];
// QGIS-style CRS selector: filter, recently used, grouped list, details; OK applies.
function CrsPicker({preferenceScope,current,close,choose,projection}:{preferenceScope:string;current:DisplayCrs;close:()=>void;choose:(c:DisplayCrs)=>void;projection?:ProjectionContext}){
 const [q,setQ]=useState(""),[sel,setSel]=useState(current);
 const recent=(()=>{try{const r=JSON.parse(localStorage.getItem(preferenceScope+":recent-crs")??"[]");return (Array.isArray(r)?r:[]).map(id=>DISPLAY_CRS.find(c=>c.id===id)).filter((c):c is DisplayCrs=>!!c)}catch{return []}})();
 const hit=(c:DisplayCrs)=>!q||n(c.name+" "+c.id+" "+c.group+" EPSG:"+(c.epsg??"")).includes(n(q));
 const groups=[...new Set(DISPLAY_CRS.map(c=>c.group))];
 const row=(c:DisplayCrs,k:string)=><button key={k} type="button" role="option" aria-selected={sel.id===c.id} className={"crs-row"+(sel.id===c.id?" active":"")} onClick={()=>setSel(c)} onDoubleClick={()=>choose(c)}><span>{c.name}</span><small>{c.epsg?"EPSG:"+c.epsg:""}</small></button>;
 return <Modal title="Hệ tọa độ hiển thị" close={close}><div className="crs-picker">
  <input type="search" autoFocus placeholder="Lọc theo tên, EPSG, tỉnh…" value={q} onChange={e=>setQ(e.target.value)} aria-label="Lọc hệ tọa độ"/>
  {!q&&recent.length>0&&<><b className="crs-group">Dùng gần đây</b>{recent.map(c=>row(c,"r"+c.id))}</>}
  <div className="crs-list" role="listbox">{groups.map(g=>{const items=DISPLAY_CRS.filter(c=>c.group===g&&hit(c));return items.length?<React.Fragment key={g}><b className="crs-group">{g}</b>{items.map(c=>row(c,c.id))}</React.Fragment>:null})}</div>
  <div className="crs-detail"><b>{sel.name}</b><small>{sel.kind==="geographic"?"Tọa độ địa lý (độ), elipsoid WGS 84":sel.kind==="mercator"?"Phép chiếu Mercator cầu, mét":"Ngang Mercator, kinh tuyến trục "+sel.lon0+"°, k₀ = "+sel.k0+", dịch Đông 500 000 m"+(sel.vn2000?" · datum VN-2000 (7 tham số TT 973/2001)":" · datum WGS 84")}</small><small>Chỉ đổi cách hiện tọa độ ở thanh trạng thái; dữ liệu và bản đồ không bị chuyển đổi.</small>{sel.kind==="tm"&&<small>Miền hiển thị kiểm tra theo kinh tuyến trục ±{sel.id.startsWith("VN2000-TM3-")?"1,5":"3"}°. Với VN-2000, tên địa danh chỉ để tra cứu; phải đối chiếu kinh tuyến, datum và hồ sơ nguồn trước khi dùng cho trắc địa.</small>}</div>
  {projection&&<Vn2000Projection key={projection.org+":"+projection.pid} {...projection}/>}
  <div className="live-actions"><button type="button" onClick={close}>Hủy</button><button type="button" className="primary" onClick={()=>choose(sel)}>OK</button></div>
 </div></Modal>;
}
export function QgisMapStatus({preferenceScope,map,ready,onCrs,projection}:{preferenceScope:string;map:React.RefObject<import("./map-surface").Map|null>;ready:boolean;onCrs:()=>void;projection?:ProjectionContext}){
 const [coord,setCoord]=useState("—"),[scale,setScale]=useState("—"),[magnify,setMagnify]=useState("100"),[angle,setAngle]=useState("0"),[render,setRender]=useState(true),[mode,setMode]=useState<"cursor"|"center"|"extent">("cursor"),[dms,setDms]=useState(false),[crs,setCrsState]=useState<DisplayCrs>(()=>{try{return findCrs(localStorage.getItem(preferenceScope+":display-crs"))}catch{return DISPLAY_CRS[0]!}}),[picking,setPicking]=useState(false);
 const setCrs=(c:DisplayCrs)=>{setCrsState(c);try{localStorage.setItem(preferenceScope+":display-crs",c.id);const r=JSON.parse(localStorage.getItem(preferenceScope+":recent-crs")??"[]");localStorage.setItem(preferenceScope+":recent-crs",JSON.stringify([c.id,...(Array.isArray(r)?r:[]).filter((x:unknown)=>x!==c.id)].slice(0,5)))}catch{/* storage unavailable */}};
 const show=(lng:number,lat:number)=>{const warning=displayCrsWarning(lng,lat,crs);if(warning)return warning;if(crs.kind==="geographic")return formatLonLat(lng,lat,dms);const [x,y]=projectForDisplay(lng,lat,crs);return x.toLocaleString("en-US",{maximumFractionDigits:2,minimumFractionDigits:2}).replace(/,/g," ")+" , "+y.toLocaleString("en-US",{maximumFractionDigits:2,minimumFractionDigits:2}).replace(/,/g," ")};const editing=useRef(""),baseZoom=useRef<number|null>(null),initialMove=useRef(false),scaleValue=useRef(0);
 const liveScale=()=>{const m=map.current;if(!m)return 0;const c=m.getCanvas(),x=c.clientWidth/2,y=c.clientHeight/2;return Math.max(1,m.unproject([x,y]).distanceTo(m.unproject([x+100,y]))/100*96/.0254)};
 useEffect(()=>{const m=map.current;if(!m||!ready)return;let frame=0;const view=(event?:{type:string})=>{const v=liveScale();scaleValue.current=v;if(baseZoom.current===null||(!initialMove.current&&event?.type==="moveend")){baseZoom.current=m.getZoom();if(event?.type==="moveend")initialMove.current=true}if(editing.current!=="scale")setScale("1:"+Math.round(v).toLocaleString("vi-VN"));if(editing.current!=="magnify")setMagnify(String(Math.max(1,Math.round(100*Math.pow(2,m.getZoom()-baseZoom.current)))));if(editing.current!=="angle")setAngle(m.getBearing().toFixed(0));if(editing.current!=="coord"){if(mode==="extent"){const b=m.getBounds();setCoord(show(b.getWest(),b.getSouth())+" : "+show(b.getEast(),b.getNorth()))}else{const p=m.getCenter();setCoord(show(p.lng,p.lat))}}};const mouse=(e:import("./map-surface").MapMouseEvent)=>{if(mode!=="cursor"||editing.current==="coord")return;cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>setCoord(show(e.lngLat.lng,e.lngLat.lat)))};view();m.on("moveend",view);m.on("resize",view);m.on("mousemove",mouse);return()=>{cancelAnimationFrame(frame);m.off("moveend",view);m.off("resize",view);m.off("mousemove",mouse)}},[ready,map,mode,dms,crs]);
 useEffect(()=>{const openPicker=()=>setPicking(true);window.addEventListener("ovg:open-crs",openPicker);return()=>window.removeEventListener("ovg:open-crs",openPicker)},[]);
 useEffect(()=>{const m=map.current;if(!m||!ready)return;m.getCanvas().style.visibility=render?"":"hidden";return()=>{m.getCanvas().style.visibility=""}},[render,ready,map]);
 function apply(k:string,scaleInput=scale){const m=map.current;editing.current="";if(!m||!ready)return;if(k==="coord"){const a=mode==="extent"||dms||crs.kind!=="geographic"?[NaN]:coord.trim().split(/[ ,]+/).map(Number);if(a.length===2&&a.every(Number.isFinite)&&Math.abs(a[0])<=180&&Math.abs(a[1])<=85.05)m.jumpTo({center:[a[0],a[1]]});else{const p=m.getCenter();setCoord(show(p.lng,p.lat))}}else if(k==="scale"){const n=Number(scaleInput.replace(/^1:/,"").replace(/[.,\s]/g,""));if(n>0&&Number.isFinite(n))m.setZoom(Math.max(0,Math.min(22,m.getZoom()+Math.log2(liveScale()/n))));else setScale("1:"+Math.round(liveScale()).toLocaleString("vi-VN"))}else if(k==="magnify"){const n=Number(magnify.replace("%",""));if(n>0&&Number.isFinite(n))m.setZoom(Math.max(0,Math.min(22,(baseZoom.current??m.getZoom())+Math.log2(n/100))));else setMagnify(String(Math.max(1,Math.round(100*Math.pow(2,m.getZoom()-(baseZoom.current??m.getZoom()))))))}else if(k==="angle"){const v=Number(angle);if(Number.isFinite(v))m.setBearing(v);else setAngle(m.getBearing().toFixed(0))}}
 const field=(k:string,v:string,change:(s:string)=>void,label:string)=> <input aria-label={label} title={label} value={v} readOnly={k==="coord"&&(mode==="extent"||dms||crs.kind!=="geographic")} onChange={e=>change(e.target.value)} onFocus={e=>{editing.current=k;e.currentTarget.select()}} onBlur={()=>{editing.current=""}} onKeyDown={e=>{if(e.key==="Enter"){e.preventDefault();apply(k);e.currentTarget.blur()}}}/>;
 return <div className="qgis-coordinates qgis-status-controls"><button className="qgis-coord-toggle" title={mode==="cursor"?"Tọa độ con trỏ · bấm để xem tâm bản đồ":mode==="center"?"Tâm bản đồ · bấm để xem phạm vi":"Phạm vi bản đồ · bấm để xem tọa độ con trỏ"} onClick={()=>setMode(v=>v==="cursor"?"center":v==="center"?"extent":"cursor")}>{mode==="cursor"?"⌖":mode==="center"?"⊕":"▭"}</button><label>{mode==="extent"?"Phạm vi":"Tọa độ"} {field("coord",coord,setCoord,mode==="extent"?"Hai góc Tây Nam : Đông Bắc (không phải bao chiếu)":crs.kind!=="geographic"||dms?"Tọa độ hiển thị · chỉ đọc":"Tọa độ kinh độ, vĩ độ · Enter để di chuyển tới")}</label>{crs.kind==="geographic"&&<button className="qgis-coord-format" title={dms?"Độ phút giây · bấm để dùng độ thập phân":"Độ thập phân · bấm để dùng độ phút giây"} onClick={()=>setDms(v=>!v)}>{dms?"DMS":"0.0°"}</button>}<label>Tỷ lệ <input list="ovg-scale-presets" aria-label="Tỷ lệ bản đồ" title="Tỷ lệ bản đồ · chọn hoặc gõ rồi Enter" value={scale} onChange={e=>{setScale(e.target.value);if(SCALES.some(n=>"1:"+n.toLocaleString("vi-VN")===e.target.value)){editing.current="scale";apply("scale",e.target.value)}}} onFocus={e=>{editing.current="scale";e.currentTarget.select()}} onBlur={()=>{editing.current=""}} onKeyDown={e=>{if(e.key==="Enter"){e.preventDefault();apply("scale");e.currentTarget.blur()}}}/><datalist id="ovg-scale-presets">{SCALES.map(n=><option key={n} value={"1:"+n.toLocaleString("vi-VN")}/>)}</datalist></label><label>Phóng đại {field("magnify",magnify,setMagnify,"Phóng đại (%)")}<span>%</span></label><label>Xoay {field("angle",angle,setAngle,"Góc xoay")}<span>°</span></label><label className="qgis-render" title="Ẩn/hiện canvas hiển thị; không thay đổi dữ liệu"><input type="checkbox" checked={render} onChange={e=>setRender(e.target.checked)}/> Render</label><button className="qgis-crs" title={"Hệ tọa độ hiển thị: "+crs.name+" · bấm để đổi"} onClick={()=>setPicking(true)}><GisIcon name="globe" size={13}/> {crs.epsg?"EPSG:"+crs.epsg:"VN-2000 TM-3 "+crs.lon0+"°"}</button>{picking&&<CrsPicker projection={projection} preferenceScope={preferenceScope} current={crs} close={()=>setPicking(false)} choose={c=>{setCrs(c);setPicking(false)}}/>}</div>
}
